"""Editorial source for ten artist study paths; examples are original studies."""
PROFILES=[
 dict(id='django',name='Django Reinhardt',focus='Arpeggi, seste, diminuiti e accompagnamento swing',
 intro='Il percorso entra nel linguaggio di Django attraverso il rapporto fra accordo, gesto ritmico e invenzione melodica. Le seste nel minore, le dominanti diminuite e i cambi di registro offrono punti di ascolto precisi. L’accompagnamento richiede un lavoro specifico di attacco e rilascio: leggere quattro accordi non equivale ancora a suonare la pompe. Sono strumenti da confrontare con registrazioni diverse, non una descrizione di tutta la sua produzione.',
 listens=[('Minor Swing — versione nella raccolta Djangology di Legacy','Segui prima gli accompagnatori e conta i quattro movimenti; al secondo ascolto cerca un punto in cui l’arpeggio si interrompe e lascia spazio alla risposta. Canta il profilo senza cercare subito tutti i tasti.'),('Djangology — stessa raccolta','Confronta l’esposizione del tema e un tratto del solo. Segna un salto di registro e un collegamento cromatico, poi descrivi come cambiano densità e intensità.')],
 sources=[('Djangology, catalogo e tracce Legacy','https://www.legacyrecordings.com/releases/djangology/')],
 links=[('5-arpeggi','Arpeggi'),('6-accordi','Accordi'),('7-progressioni','Progressioni')],
 theory=['5-accordi','7-armonia-cromatica','8-armonia-diminuita'],
 analysis='Nell’esercizio 02 Sol♯–Si–Re–Fa, sopra Mi, diventa 3–5–♭7–♭9. Il gruppo diminuito non coincide con la fondamentale della dominante; l’arrivo su Do nella terza battuta chiarisce Am6. Il Fa♯ degli esempi in Am6 è invece sesta maggiore della tonica minore: distinguere i due Fa impedisce di usare un’unica scala indifferenziata.',
 compare='Suona l’arpeggio di Am e aggiungi prima Fa naturale, poi Fa♯. Ascolta il cambiamento sopra Am6; poi sposta Fa naturale sulla dominante E7(♭9), dove assume un’altra relazione.',
 criterion='Riesci a far sentire la sesta maggiore nel minore, a risolvere la dominante e a mantenere quattro attacchi regolari senza irrigidire la mano?',
 continuation='Confronta il tuo accompagnamento con la registrazione: scegli un solo aspetto da correggere, durata degli accordi oppure rilievo di secondo e quarto movimento. Per la mano solistica studia le pennate in appoggio lentamente, senza imporre una diteggiatura biografica o limitare artificialmente le dita.'),
 dict(id='christian',name='Charlie Christian',focus='Riff, swing, linea singola e note guida',
 intro='Qui il punto di partenza è il riff: un’idea breve che può sostenere ripetizione, risposta e sviluppo. Il suono della chitarra elettrica permette di lavorare su chiarezza dell’attacco e continuità della linea senza perdere la funzione ritmica. Le frasi degli esercizi attraversano seste, dominanti e II–V–I; il loro valore sta nel rapporto con i cambi e con la pulsazione.',
 listens=[('Rose Room — Benny Goodman Sextet con Charlie Christian, nelle incisioni raccolte in The Genius of the Electric Guitar','Isola l’ingresso della chitarra e conta per quante battute sviluppa un’idea prima di cambiarla. Canta una risposta di due battute e annota dove respira.'),('Seven Come Eleven — Benny Goodman Sextet con Charlie Christian, nella stessa raccolta','Distingui il materiale di riff dalle frasi improvvisate. Batti secondo e quarto movimento e confronta l’attacco delle note lunghe con quello delle crome.')],
 sources=[('Charlie Christian, catalogo Legacy e collegamenti di ascolto','https://www.legacyrecordings.com/artists/charlie-christian/'),('Solo Flight: archivio discografico delle incisioni','https://soloflight.cc/')],
 links=[('7-progressioni','Progressioni'),('8-licks','Licks')],theory=['6-armonia-funzionale','12-ritmo-sviluppo'],
 analysis='Nell’esercizio 03 il Fa è terza di Dm7 e settima di G7. Il Si della dominante conduce al Mi della tonica: i bersagli descrivono il II–V–I anche quando la linea rinuncia ai cromatismi. Nell’esercizio 04 un riff di 3–5–♭7–13 viene adattato a tre dominanti: si conserva la relazione, non l’altezza assoluta.',
 compare='Riduci il II–V–I a Fa–Fa–Mi, poi reinserisci le note intermedie. Confronta un riff trasposto meccanicamente e uno adattato alla qualità degli accordi.',
 criterion='Il riff resta riconoscibile quando cambia accordo? Sai cantare il punto di arrivo e mantenere lo swing durante le pause?',
 continuation='Inserisci due battute del riff in un blues completo di dodici battute. Lascia il resto più rarefatto e verifica di ritrovare la forma: le quattro battute dell’esercizio 04 sono solo una finestra di lavoro.'),
 dict(id='wes',name='Wes Montgomery',focus='Ottave, suono e crescita dalla linea agli accordi',
 intro='Il percorso studia la relazione fra un motivo e la sua tessitura: prima una linea, poi ottave, infine accordi. Questo arco è una possibilità di organizzazione da ascoltare e sperimentare, non uno schema obbligatorio per ogni solo di Montgomery. La chiarezza del canto e il controllo delle corde mute precedono il volume e la velocità. Il pollice è una scelta tecnica da esplorare con rilassatezza.',
 listens=[('Four on Six — The Incredible Jazz Guitar of Wes Montgomery','Distingui tema e solo, poi segna un cambiamento di registro o densità. Controlla se il nuovo materiale sviluppa qualcosa già ascoltato invece di limitarti a contare le note.'),('D-Natural Blues — stesso album','Segui la forma del blues, il rapporto con la sezione ritmica e l’articolazione delle risposte. Confronta un passaggio a note singole con uno più denso che individui nell’ascolto.')],
 sources=[('The Incredible Jazz Guitar, Concord','https://concord.com/concord-albums/the-incredible-jazz-guitar/'),('Approfondimento della Library of Congress','https://www.loc.gov/static/programs/national-recording-preservation-board/documents/IncredibleJazzGuitarWesMontgomery.pdf')],
 links=[('3-conoscere-la-tastiera','Tastiera'),('6-accordi','Accordi'),('7-progressioni','Progressioni')],theory=['3-intervalli','5-accordi','12-ritmo-sviluppo'],
 analysis='Nell’esercizio 02 le due altezze di ogni ottava distano dodici semitoni e hanno lo stesso nome: la raddoppiatura non cambia la qualità armonica della nota scelta. Nello studio 06 il passaggio linea → ottave → accordi aumenta densità e registro senza modificare tempo e durata della forma. Questa trasformazione di tessitura è una forma di sviluppo.',
 compare='Esegui il medesimo motivo a note singole e in ottave mantenendo lo stesso ritmo; poi armonizza solo due arrivi. Ascolta separatamente l’effetto del registro, del raddoppio e dell’armonia.',
 criterion='Si sente il canto superiore e rimane muta la corda interna? Il passaggio alle ottave o agli accordi continua la frase senza accelerare?',
 continuation='Crea un chorus su una progressione già studiata e pianifica soltanto i punti di cambio della tessitura. Il resto deve essere una frase musicale, non una dimostrazione continua di ottave.'),
 dict(id='hall',name='Jim Hall',focus='Spazio, motivi, dialogo e movimento delle voci',
 intro='Il lavoro riguarda la scelta di quando intervenire e quali voci mettere in relazione. Una cellula breve può svilupparsi attraverso silenzio, spostamento e risposta; le coppie di note possono far sentire un accordo senza riempire tutto il registro. L’ascolto in duo aiuta a distinguere iniziativa, sostegno e dialogo: il compito non è riprodurre ogni accordo che si conosce.',
 listens=[('My Funny Valentine — Bill Evans e Jim Hall, Undercurrent; versione principale, non la take alternativa','Ascolta una volta seguendo solo il pianoforte e una volta solo la chitarra. Scegli un punto in cui una parte lascia spazio e descrivi che cosa fa l’altra.'),('Romain — stesso album, versione principale','Cerca una cellula che ritorna e una risposta che la modifica. Segna pause e cambi di densità prima di analizzare le sigle.')],
 sources=[('Jim Hall, profilo Blue Note','https://www.bluenote.com/artist/jim-hall/'),('Jim Hall, archivio ufficiale','https://www.jimhallmusic.com/')],
 links=[('6-accordi','Accordi'),('7-progressioni','Progressioni'),('9-modern-jazz-fusion','Modern jazz e fusion')],theory=['6-armonia-funzionale','10-armonia-non-funzionale','12-ritmo-sviluppo'],
 analysis='Nell’esercizio 03 Do–Fa e Re–Fa arrivano a Si–Fa sopra G7; poi il Fa scende a Mi e il Si resta fermo su Cmaj7. Il collegamento descrive una risoluzione con un movimento minimo. Nell’esercizio 05 la cellula viene spostata di una croma: la pausa finale si accorcia per conservare la misura.',
 compare='Canta la voce alta e suona la bassa, poi inverti i ruoli. Nella frase ritmica mantieni le note uguali e sposta soltanto l’inizio: valuta se resta riconoscibile.',
 criterion='Sai contare le pause e cantare entrambe le voci? Le risposte continuano ciò che precede, invece di aggiungere materiale senza relazione?',
 continuation='Suona in duo distribuendo una frase a testa. Nel secondo tentativo chi accompagna usa al massimo due note per attacco; riascoltate se emerge un dialogo o una semplice alternanza.'),
 dict(id='metheny',name='Pat Metheny',focus='Arco melodico, intervalli ampi e sviluppo modale',
 intro='Il percorso prende come ingresso il trio e la costruzione di melodie che attraversano registri diversi. Pedali, salti e riprese del motivo permettono di progettare un arco senza affidarsi soltanto alle cadenze. Le attività non esauriscono i molti organici e linguaggi di Metheny: invitano ad ascoltare come la melodia dialoga con basso e batteria e come una frase trova il proprio respiro.',
 listens=[('Bright Size Life — album omonimo, trio con Jaco Pastorius e Bob Moses','Canta il profilo del tema e individua un salto e un ritorno al registro centrale. Poi ascolta il basso come interlocutore, non soltanto come fondamentale.'),('Sirabhorn — stesso album','Segui la lunghezza delle frasi e i punti di respiro. Confronta due esposizioni di un’idea e annota se cambiano ritmo, registro o conclusione.')],
 sources=[('Bright Size Life, ECM: musicisti e tracce','https://ecmrecords.com/product/bright-size-life-pat-metheny/'),('Bright Size Life, discografia ufficiale','https://www.patmetheny.com/music/detail.cfm?id=17')],
 links=[('4-scale','Scale'),('7-progressioni','Progressioni'),('9-modern-jazz-fusion','Modern jazz e fusion')],theory=['4-scale','10-armonia-non-funzionale','12-ritmo-sviluppo'],
 analysis='Nell’esercizio 02 Mi–Sol–Si–Re su Re dà 9–11–13–1. Il Fa dell’accompagnamento stabilisce il minore, il Si naturale caratterizza il dorico. Nell’esercizio 04 Re–Fa♯–La sopra Cmaj7 produce 9–♯11–13; il Mi conclusivo chiarisce la terza. Le stesse triadi sono unità melodiche, non nuovi centri automaticamente stabiliti.',
 compare='Mantieni le altezze Mi–Sol–Si–Re e confronta Cmaj7 e Dm7 come sostegno: cambiano i gradi e i punti di riposo. Scrivi poi una risposta che rispetti il profilo ma scelga un finale diverso.',
 criterion='Riesci a cantare il salto prima di suonarlo e a sentire il culmine della frase? Il centro rimane chiaro anche senza cadenza V–I?',
 continuation='Registra otto battute su un pedale con due soli salti ampi e molte note di collegamento. Poi riduci gli attacchi di un terzo conservando culmine e punti di respiro.'),
 dict(id='pass',name='Joe Pass',focus='Chitarra sola: basso, canto e voci interne',
 intro='Qui la chitarra assume più funzioni nello stesso tempo: suggerisce il basso, sostiene l’armonia e rende riconoscibile una melodia. Prima alterniamo i registri, poi sovrapponiamo voci con durate indipendenti. Le versioni complete sono per chitarra sola: non viene aggiunto un bassista che nasconda il compito. La semplicità del giro permette di ascoltare equilibrio e continuità.',
 listens=[('Night and Day — Joe Pass, Virtuoso','Ascolta prima il canto e poi i suoni bassi. Individua un passaggio in cui basso e melodia si alternano e uno in cui si sovrappongono.'),('Stella by Starlight — stesso album','Segna un punto in cui la densità si riduce e uno in cui aumenta. Conta la forma anche durante le linee a nota singola: quali arrivi fanno riconoscere gli accordi?')],
 sources=[('Virtuoso, catalogo Concord','https://concord.com/concord-albums/virtuoso-original-jazz-classics-remasters/'),('Joe Pass, profilo Concord','https://concord.com/artist/joe-pass/')],
 links=[('6-accordi','Accordi'),('7-progressioni','Progressioni')],theory=['5-accordi','6-armonia-funzionale','12-ritmo-sviluppo'],
 analysis='Nell’esercizio 04 il basso si muove in quarti, le due voci superiori in minime. Su G7 si ascoltano prima Fa–Si e poi Re–Sol; su Cmaj7 seguono Mi–Si e Sol–Do. L’armonia è resa udibile da tre linee simultanee e dal contesto. Tonica, terza e quinta occupano il basso; non sono introdotte tensioni come note più gravi.',
 compare='Riduci il passaggio a due voci: basso e canto. Aggiungi solo dopo la voce interna, osservando quali note possono continuare a risuonare fra due attacchi del basso.',
 criterion='Le note alte tengono la loro durata mentre il basso continua? Il canto rimane più presente delle voci interne e la forma si riconosce senza altri strumenti?',
 continuation='Prepara quattro battute di una progressione con un basso semplice e una melodia cantabile. Scrivi prima le due linee separate, controlla la compatibilità delle corde, poi inserisci soltanto le voci interne indispensabili.'),
 dict(id='benson',name='George Benson',focus='Blues, bebop, articolazione e canto',
 intro='Il percorso collega una linea che si può cantare al controllo delle dita e del ritmo. Terza blues, terza maggiore e cromatismi brevi lavorano insieme a pause e punti di arrivo; alcuni esercizi usano swing, altri un groove regolare. L’ascolto di Benson come strumentista e cantante aiuta a evitare che la tecnica diventi una sequenza di diteggiature senza respiro.',
 listens=[('Breezin’ — George Benson, album omonimo','Confronta il tema con i passaggi successivi di chitarra: cerca una frase che rimanga cantabile mentre aumenta la densità. Segui il rapporto fra linea e accompagnamento.'),('This Masquerade — stesso album','Distingui esposizione cantata, interventi della chitarra e passaggi di dialogo fra voce e strumento. Scegli una breve risposta, cantane il ritmo e prova a descriverne l’articolazione.')],
 sources=[('George Benson su Breezin’, intervista Rhino','https://www.rhino.com/article/the-rhino-interview-george-benson'),('George Benson, intervista e profilo NEA','https://www.arts.gov/honors/jazz/george-benson')],
 links=[('5-arpeggi','Arpeggi'),('8-licks','Licks'),('9-modern-jazz-fusion','Modern jazz e fusion')],theory=['6-armonia-funzionale','10-armonia-non-funzionale','12-ritmo-sviluppo'],
 analysis='Nell’esercizio 01 Mi♭ e Mi naturale su C7 distinguono terza blues e terza maggiore. Nell’esercizio 03 Si♭ prepara il Si di G7 e Fa–Mi♭ circonda il Mi di C6: il cromatismo acquista senso rispetto al bersaglio e alla sua durata. Gli esercizi 04 e 06 passano a sedicesimi regolari; il cambiamento ritmico è esplicito e non coincide con un semplice aumento del tempo.',
 compare='Canta e suona la stessa frase senza cromatismi, poi reinserisci Mi♭–Mi. Confronta una versione swing e una regolare conservando la forma; evita di far partire contemporaneamente i due audio.',
 criterion='Sai cantare il punto di arrivo e riprodurlo con le dita? Il passaggio dal blues alla linea bebop e al groove conserva accenti, pause e direzione?',
 continuation='Canta una risposta di una battuta e riproducila sulla chitarra prima di variarla. Usa un registro vocale comodo e alterna voce e strumento se il raddoppio simultaneo ti fa perdere il tempo.'),
 dict(id='martino',name='Pat Martino',focus='Aree minori, continuità e rilettura delle dominanti',
 intro='Organizziamo la linea intorno a un’area minore riconoscibile e osserviamo come cambia significato sopra accordi diversi. La continuità delle crome richiede controllo del percorso e dei bersagli, non soltanto velocità. Le conversioni qui sono esempi circoscritti e verificati nota per nota; il materiale didattico di Martino approfondisce un sistema più ampio, che non viene ridotto a una formula universale.',
 listens=[('Just Friends — Pat Martino, El Hombre','Segui una frase attraverso il cambio di accordo. Canta le sue note di arrivo e osserva se il disegno mantiene continuità pur cambiando funzione.'),('Waltz for Geri — stesso album','Conta la pulsazione ternaria e confronta le lunghezze delle frasi con Just Friends. Il metro dell’ascolto non è quello dei nostri esercizi, scritti in 4/4.')],
 sources=[('El Hombre, Concord','https://concord.com/concord-albums/el-hombre/'),('The Nature of Guitar, lezioni di Pat Martino su TrueFire','https://truefire.com/courses/pat-martino/the-nature-of-guitar/c1002')],
 links=[('4-scale','Scale'),('5-arpeggi','Arpeggi'),('7-progressioni','Progressioni'),('8-licks','Licks')],theory=['4-scale','6-armonia-funzionale','7-armonia-cromatica'],
 analysis='Nell’esercizio 02 Re–Fa–La–Do sopra G7 dà 5–♭7–9–11 e non contiene il Si, terza della dominante. Il Si aggiunto chiarisce quella qualità prima del Mi sul I. Nell’esercizio 05 la triade di La♭ minore dà ♭9–3 enarmonica–♭13 su G7: è un colore diverso, da risolvere, non l’equivalenza letterale di due accordi.',
 compare='Suona Dm7 prima su basso Re e poi su basso Sol. Mantieni le altezze e ricalcola i gradi; aggiungi Si e ascolta che cosa rende udibile la dominante. Confronta poi La♭–Si–Mi♭, senza mescolare le due scelte automaticamente.',
 criterion='Sai nominare i gradi dell’area minore rispetto al basso reale e fare sentire la terza della dominante? La linea continua anche quando cambia il punto di arrivo?',
 continuation='Prendi un II–V–I e costruisci due versioni: area minore del II prolungata sul V, poi colore alterato sul V. Mantieni identici tempo e risoluzione per confrontare realmente le scelte.'),
 dict(id='scofield',name='John Scofield',focus='Blues, groove, doppie note e tensione con rientro',
 intro='Il percorso mette in relazione il carattere blues con una griglia ritmica precisa. Pause, attacchi spostati e doppie note possono contare più di una scala nuova; brevi spostamenti cromatici diventano chiari quando il rientro conserva il groove. Il timbro e le inflessioni fanno parte dell’ascolto: l’audio sintetico degli esercizi verifica ritmo e altezze e non riproduce quelle sfumature.',
 listens=[('Do Like Eddie — John Scofield, Hand Jive','Segui cassa e basso prima della chitarra. Segna una pausa della linea e prova a cantare dove rientra rispetto al groove.'),('Dark Blue — stesso album','Individua un gesto blues e una risposta più dissonante. Confronta durata della tensione e chiarezza del punto d’arrivo senza attribuire una scala a ogni singola nota.')],
 sources=[('Hand Jive, Blue Note: tracce e organico','https://store.bluenote.com/products/john-scofield-hand-jive-2lp-blue-note-classic-vinyl-edition'),('John Scofield, biografia ufficiale','https://www.johnscofield.com/bio/')],
 links=[('7-progressioni','Progressioni'),('8-licks','Licks'),('9-modern-jazz-fusion','Modern jazz e fusion')],theory=['7-armonia-cromatica','10-armonia-non-funzionale','12-ritmo-sviluppo'],
 analysis='Nell’esercizio 03 Mi–Sol–Si♭–Do su C7 diventa Fa–La♭–Si–Re♭ per mezza battuta e ritorna. Fa resta nel contesto mixolidio, le altre tre note producono attriti più marcati. Il side-slip dipende dal parallelismo riconoscibile e dal rientro sul Mi, non dal fatto che tutte le note siano esterne.',
 compare='Suona la stessa uscita con ritmo continuo e poi separata da una pausa; confronta quanto è percepibile il collegamento. Riduci a una nota il ritmo sincopato dell’esercizio 02 e verifica se resta un groove.',
 criterion='Sai mantenere la suddivisione nelle pause e cantare il rientro prima dell’uscita? Le doppie note sostengono la frase senza coprire l’accompagnamento?',
 continuation='Costruisci otto battute con una sola uscita e almeno due pause lunghe. Sul secondo giro conserva gli stessi punti di rientro ma cambia l’articolazione: registra e confronta.'),
 dict(id='mclaughlin',name='John McLaughlin',focus='Cellule, accenti, metri dispari e sviluppo modale',
 intro='Il percorso entra nel rapporto fra energia, precisione e organizzazione del tempo. Cellule regolari, accenti che attraversano la battuta e metri dispari richiedono prima una comprensione cantata. Il lavoro elettrico di Mahavishnu e quello acustico di Shakti aprono ascolti diversi. I raggruppamenti semplici dei nostri esercizi sono propedeutici: non sostituiscono lo studio dei sistemi ritmici indiani e non vengono presentati come tāla tradizionali.',
 listens=[('The Inner Mounting Flame — Mahavishnu Orchestra, con John McLaughlin','Scegli il primo tema e separa pulsazione, accenti e disegno melodico. Cerca un punto in cui gli strumenti condividono gli attacchi e uno in cui le parti si differenziano.'),('Shakti — album del gruppo con John McLaughlin','Scegli una breve frase e segui la risposta fra chitarra e percussioni. Confronta attacco, spazio e articolazione con l’ascolto elettrico, senza presumere che la stessa griglia ritmica spieghi entrambi.')],
 sources=[('Musical Life, racconto e discografia di John McLaughlin','https://www.johnmclaughlin.com/musical-life/')],
 links=[('4-scale','Scale'),('9-modern-jazz-fusion','Modern jazz e fusion')],theory=['4-scale','10-armonia-non-funzionale','12-ritmo-sviluppo'],
 analysis='Nell’esercizio 04 tre sedicesimi si ripetono per tre battute di 4/4: 48 suddivisioni contengono sedici cellule e riportano l’accento all’inizio della misura. Il metro non cambia. Nello studio 06 cambia invece la misura: sette crome raggruppate 2+2+3. Mi♭ sopra Re rende riconoscibile il materiale frigio, distinto dal Mi naturale dorico di altri esercizi.',
 compare='Suona una sola altezza e confronta accenti ogni tre sedicesimi in 4/4 e una battuta di 7/8. Poi aggiungi Re–Mi♭–Fa e ascolta separatamente l’effetto del colore modale e del metro.',
 criterion='Sai cantare il ciclo e riconoscere l’inizio della battuta senza la chitarra? Densità e velocità mantengono rilassatezza, pulizia e un punto di arrivo?',
 continuation='Alterna due battute dense e due rarefatte senza cambiare tempo. Per approfondire il rapporto con le tradizioni indiane parti dalle lezioni e collaborazioni documentate dall’artista, mantenendo distinti esercizi introduttivi e sistemi ritmici completi.'),
]
